  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C10"],
      "claim": "Apomorphine, the highest-transfer analogue, readily crossed the BBB in rats after subcutaneous dosing, with brain concentrations exceeding plasma (8 ng/g vs 2 ng/ml), directly demonstrating meaningful CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Cinchophen showed brain concentrations of 42 mg/kg after oral dosing in dogs, with little hindrance to BBB passage, supporting meaningful CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "S(+)-apomorphine in mice had a brain-to-plasma AUCinfinity ratio of 228%, confirming substantial CNS penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Compound 21j showed brain and CSF penetration with low susceptibility to P-glycoprotein transporters in rats, indicating meaningful CNS access without major efflux liability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Yohimbine demonstrated brain uptake in a first-in-man PET study, providing human evidence of BBB penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "N-propylnorapomorphine showed good brain penetration ex vivo in rats and in vivo by PET in nonhuman primates, corroborating CNS access.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All retrieved experimental evidence, with high transfer scores, demonstrates meaningful CNS access for related molecules across species (rat, mouse, dog, primate, human), including direct brain/plasma, CSF, and PET measurements. No evidence points to inadequate BBB penetration; therefore the query is predicted to have meaningful CNS access.",
